// Ferramentas: uma página por ferramenta em /ferramentas/{slug}/.
// Campos: id legado (âncora de /ferramentas.html#id), grupo, títulos, conteúdo editorial,
// formulário (HTML gerado pelos auxiliares abaixo) e o script em js/ferramentas/{slug}.js.
// Valores de referência sempre editáveis pelo usuário; quando não há fonte oficial, o texto diz que é estimativa.

const ANEEL_BANDEIRAS = ["ANEEL: bandeiras tarifárias (valores vigentes)", "https://www.gov.br/aneel/pt-br/assuntos/tarifas/bandeiras-tarifarias"];
const INMETRO_AR = ["Inmetro/PBE: tabela de eficiência de condicionadores de ar (consumo anual em ciclo de 2.080 h)", "https://www.gov.br/inmetro/pt-br/assuntos/avaliacao-da-conformidade/programa-brasileiro-de-etiquetagem/tabelas-de-eficiencia-energetica/condicionadores-de-ar/condicionadores-de-ar-indices-novos-idrs.pdf"];
const ANVISA = ["Anvisa: cuidados com misturas caseiras de produtos de limpeza", "https://www.gov.br/anvisa/pt-br/assuntos/noticias-anvisa/2025/todo-cuidado-e-pouco-com-as-misturas-caseiras-para-limpeza-1/"];
const QUARTZOLIT_ARGAMASSA = ["Quartzolit: boletim técnico de argamassa (4 kg/m² na base; 8 kg/m² com dupla colagem)", "https://www.quartzolit.weber/files/br/2018-08/BT_-_piso_sobre_piso_interno_branco_quartzolit_Rev._04.2018.pdf"];

// Auxiliares de formulário. Campos numéricos usam type="text" + inputmode="decimal" para aceitar vírgula.
export const campo = (name, label, value, { unidade = "", ajuda = "", modo = "decimal", obrigatorio = true } = {}) =>
  `<label class="campo" for="f-${name}"><span>${label}</span><span class="input-unit"><input id="f-${name}" name="${name}" type="text" inputmode="${modo}" autocomplete="off" value="${value}"${obrigatorio ? " required" : ""}>${unidade ? `<em>${unidade}</em>` : ""}</span>${ajuda ? `<small>${ajuda}</small>` : ""}</label>`;
export const escolha = (name, label, opcoes, { ajuda = "" } = {}) =>
  `<label class="campo" for="f-${name}"><span>${label}</span><select id="f-${name}" name="${name}">${opcoes.map(([v, t, sel]) => `<option value="${v}"${sel ? " selected" : ""}>${t}</option>`).join("")}</select>${ajuda ? `<small>${ajuda}</small>` : ""}</label>`;
export const marca = (name, label) => `<label class="check-inline" for="f-${name}"><input id="f-${name}" name="${name}" type="checkbox"> ${label}</label>`;
const grade = (...c) => `<div class="form-grid">${c.join("")}</div>`;
const premissas = (...c) => `<details class="premissas"><summary>Ajustar premissas</summary>${grade(...c)}</details>`;

export const grupos = ["Reforma e obra", "Energia e conforto", "Decoração", "Rotina"];

